/// Merged Natural Earth 1:110m continent selectable in [`WorldMap`].
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub enum Continent {
    /// North America (`"north-america"`).
    NorthAmerica,
    /// South America (`"south-america"`).
    SouthAmerica,
    /// Europe (`"europe"`, default).
    #[default]
    Europe,
    /// Africa (`"africa"`).
    Africa,
    /// Asia (`"asia"`).
    Asia,
    /// Oceania (`"oceania"`).
    Oceania,
}

impl Continent {
    /// All six selectable continents in switcher menu order.
    pub const ALL: [Self; 6] = [
        Self::NorthAmerica,
        Self::SouthAmerica,
        Self::Europe,
        Self::Africa,
        Self::Asia,
        Self::Oceania,
    ];

    /// Kebab-case slug identifier (`"europe"`, `"north-america"`, etc.).
    pub const fn as_slug(self) -> &'static str {
        match self {
            Self::NorthAmerica => "north-america",
            Self::SouthAmerica => "south-america",
            Self::Europe => "europe",
            Self::Africa => "africa",
            Self::Asia => "asia",
            Self::Oceania => "oceania",
        }
    }

    /// Parse a continent from its slug or display name (case-insensitive).
    pub fn from_slug(value: &str) -> Option<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "north-america" | "north america" | "north_america" => Some(Self::NorthAmerica),
            "south-america" | "south america" | "south_america" => Some(Self::SouthAmerica),
            "europe" => Some(Self::Europe),
            "africa" => Some(Self::Africa),
            "asia" => Some(Self::Asia),
            "oceania" => Some(Self::Oceania),
            _ => None,
        }
    }

    /// Localized display name matching the active [`UiLanguage`].
    pub fn label(self, cx: &App) -> &'static str {
        match self {
            Self::NorthAmerica => tr(cx, "North America", "北美洲"),
            Self::SouthAmerica => tr(cx, "South America", "南美洲"),
            Self::Europe => tr(cx, "Europe", "欧洲"),
            Self::Africa => tr(cx, "Africa", "非洲"),
            Self::Asia => tr(cx, "Asia", "亚洲"),
            Self::Oceania => tr(cx, "Oceania", "大洋洲"),
        }
    }

    /// Zero-based index (`0..6`) in [`Self::ALL`].
    pub const fn index(self) -> usize {
        match self {
            Self::NorthAmerica => 0,
            Self::SouthAmerica => 1,
            Self::Europe => 2,
            Self::Africa => 3,
            Self::Asia => 4,
            Self::Oceania => 5,
        }
    }

    /// SVG `<path d="...">` silhouette on the `540 × 242` map viewBox.
    pub const fn svg_path(self) -> &'static str {
        match self {
            Self::NorthAmerica => NORTH_AMERICA_PATH,
            Self::SouthAmerica => SOUTH_AMERICA_PATH,
            Self::Europe => EUROPE_PATH,
            Self::Africa => AFRICA_PATH,
            Self::Asia => ASIA_PATH,
            Self::Oceania => OCEANIA_PATH,
        }
    }

    /// Visual focal origin `(x, y)` in `540 × 242` viewBox coordinates used during continent settle.
    pub const fn origin(self) -> (f32, f32) {
        match self {
            Self::NorthAmerica => (141.0, 49.0),
            Self::SouthAmerica => (181.0, 162.0),
            Self::Europe => (302.0, 36.0),
            Self::Africa => (296.0, 121.0),
            Self::Asia => (385.0, 56.0),
            Self::Oceania => (462.0, 185.0),
        }
    }
}

/// Events emitted by [`WorldMap`] when the highlighted continent or switcher menu changes.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum WorldMapEvent {
    /// Highlighted continent changed via the interactive switcher or keyboard navigation.
    ContinentChanged(Continent),
    /// Switcher listbox opened or closed.
    MenuOpenChanged(bool),
}

impl EventEmitter<WorldMapEvent> for WorldMap {}

struct CoastlineGeometry {
    pts: Vec<(f32, f32)>,
    norm_s: Vec<f32>,
    #[cfg_attr(not(test), allow(dead_code))]
    arc_length: f32,
}

/// Scan compact SVG signed float tokens (such as `"2.3-.5"` or `".9 0-1.1 .6"`).
fn scan_svg_numbers(input: &str) -> Vec<f32> {
    let bytes = input.as_bytes();
    let len = bytes.len();
    let mut i = 0usize;
    let mut out = Vec::new();
    while i < len {
        let b = bytes[i];
        let starts_num = b.is_ascii_digit()
            || b == b'.'
            || ((b == b'-' || b == b'+')
                && i + 1 < len
                && (bytes[i + 1].is_ascii_digit() || bytes[i + 1] == b'.'));
        if !starts_num {
            i += 1;
            continue;
        }
        let start = i;
        if bytes[i] == b'-' || bytes[i] == b'+' {
            i += 1;
        }
        let mut seen_dot = false;
        while i < len {
            let c = bytes[i];
            if c.is_ascii_digit() {
                i += 1;
            } else if c == b'.' && !seen_dot {
                seen_dot = true;
                i += 1;
            } else {
                break;
            }
        }
        if let Ok(s) = std::str::from_utf8(&bytes[start..i])
            && let Ok(val) = s.parse::<f32>()
        {
            out.push(val);
        }
    }
    out
}

fn parse_main_coastline(path_d: &str) -> CoastlineGeometry {
    let z_end = path_d.find(['z', 'Z']).map_or(path_d.len(), |idx| idx + 1);
    let main_d = &path_d[..z_end];
    let nums = scan_svg_numbers(main_d);
    let mut pts = Vec::with_capacity(nums.len() / 2 + 1);
    if nums.len() >= 2 {
        let mut cx = nums[0];
        let mut cy = nums[1];
        pts.push((cx, cy));
        let mut k = 2usize;
        while k + 1 < nums.len() {
            cx += nums[k];
            cy += nums[k + 1];
            pts.push((cx, cy));
            k += 2;
        }
        pts.push(pts[0]);
    }
    let mut cum = Vec::with_capacity(pts.len());
    let mut total = 0.0f32;
    cum.push(0.0);
    for i in 1..pts.len() {
        let dx = pts[i].0 - pts[i - 1].0;
        let dy = pts[i].1 - pts[i - 1].1;
        total += (dx * dx + dy * dy).sqrt();
        cum.push(total);
    }
    let inv = 1000.0 / total.max(1e-4);
    let norm_s = cum.into_iter().map(|c| c * inv).collect();
    CoastlineGeometry {
        pts,
        norm_s,
        arc_length: total,
    }
}

fn coastline_cache(continent: Continent) -> &'static CoastlineGeometry {
    static CACHE: OnceLock<[CoastlineGeometry; 6]> = OnceLock::new();
    let arr = CACHE.get_or_init(|| Continent::ALL.map(|c| parse_main_coastline(c.svg_path())));
    &arr[continent.index()]
}

fn point_in_polygon(vx: f32, vy: f32, pts: &[(f32, f32)]) -> bool {
    if pts.len() < 3 {
        return false;
    }
    let mut inside = false;
    let mut j = pts.len() - 1;
    for i in 0..pts.len() {
        let (xi, yi) = pts[i];
        let (xj, yj) = pts[j];
        let intersects = ((yi > vy) != (yj > vy))
            && (vx < (xj - xi) * (vy - yi) / (yj - yi).copysign((yj - yi).abs().max(1e-5)) + xi);
        if intersects {
            inside = !inside;
        }
        j = i;
    }
    inside
}

/// Hit-test a `540 × 242` viewBox coordinate `(vx, vy)` against the 6 continents.
fn hit_continent_vb(vx: f32, vy: f32) -> Option<Continent> {
    if !(0.0..=MAP_VB_W).contains(&vx) || !(0.0..=MAP_VB_H).contains(&vy) {
        return None;
    }
    for c in Continent::ALL {
        if point_in_polygon(vx, vy, &coastline_cache(c).pts) {
            return Some(c);
        }
    }
    // Coastal / island proximity fallback (`<= 7.5` viewBox units)
    let mut best: Option<(Continent, f32)> = None;
    for c in Continent::ALL {
        let pts = &coastline_cache(c).pts;
        let min_d2 = pts
            .iter()
            .step_by(2)
            .map(|&(px_x, px_y)| {
                let dx = vx - px_x;
                let dy = vy - px_y;
                dx * dx + dy * dy
            })
            .fold(f32::INFINITY, f32::min);
        if min_d2 <= 56.25 && best.is_none_or(|(_, b_d2)| min_d2 < b_d2) {
            best = Some((c, min_d2));
        }
    }
    best.map(|(c, _)| c)
}

/// Sample the diagonal pastel coastline shine (`(0,0) -> (540,242)`).
#[cfg_attr(not(test), allow(dead_code))]
fn coastline_pastel_color(ax: f32, ay: f32) -> Hsla {
    let denom = MAP_VB_W * MAP_VB_W + MAP_VB_H * MAP_VB_H;
    let u = ((ax * MAP_VB_W + ay * MAP_VB_H) / denom).clamp(0.0, 1.0);
    let c0: Hsla = rgb(0xffa0ab).into();
    let c1: Hsla = rgb(0xffb89e).into();
    let c2: Hsla = rgb(0xc8a8e5).into();
    let c3: Hsla = rgb(0xa8b5ff).into();
    if u < 0.33 {
        pro_mix_color(c0, c1, u / 0.33)
    } else if u < 0.66 {
        pro_mix_color(c1, c2, (u - 0.33) / 0.33)
    } else {
        pro_mix_color(c2, c3, (u - 0.66) / 0.34)
    }
}

/// Build an SVG `<path d="...">` sub-arc `[start_s .. start_s + span_s]` (modulo `1000.0`) along `geo`.
fn build_coastline_svg_d(geo: &CoastlineGeometry, start_s: f32, span_s: f32) -> String {
    use std::fmt::Write as _;
    if geo.pts.len() < 2 || span_s <= 0.5 {
        return String::new();
    }
    let s0 = start_s.rem_euclid(1000.0);
    let s1 = s0 + span_s;
    let ranges: [(f32, f32); 2] = if s1 <= 1000.0 {
        [(s0, s1), (0.0, 0.0)]
    } else {
        [(s0, 1000.0), (0.0, s1 - 1000.0)]
    };

    let mut out = String::with_capacity(1400);
    for (ca, cb) in ranges {
        if cb - ca <= 0.05 {
            continue;
        }
        let mut started = false;
        for i in 0..(geo.pts.len() - 1) {
            let sa = geo.norm_s[i];
            let sb = geo.norm_s[i + 1];
            if sb <= ca || sa >= cb {
                continue;
            }
            let seg = (sb - sa).max(1e-4);
            let u0 = ((ca - sa) / seg).clamp(0.0, 1.0);
            let u1 = ((cb - sa) / seg).clamp(0.0, 1.0);
            let x0 = geo.pts[i].0 + (geo.pts[i + 1].0 - geo.pts[i].0) * u0;
            let y0 = geo.pts[i].1 + (geo.pts[i + 1].1 - geo.pts[i].1) * u0;
            let x1 = geo.pts[i].0 + (geo.pts[i + 1].0 - geo.pts[i].0) * u1;
            let y1 = geo.pts[i].1 + (geo.pts[i + 1].1 - geo.pts[i].1) * u1;
            if !started {
                let _ = write!(out, "M{x0:.2} {y0:.2}");
                started = true;
            }
            let _ = write!(out, "L{x1:.2} {y1:.2}");
        }
    }
    out
}

/// Unclipped multi-pass concentric SVG `<path>` aurora under-glow (`0` `<filter>` clipping, solid stroke hexes for 100% `usvg` reliability).
fn continent_under_glow_svg(continent: Continent, step: usize) -> Arc<Image> {
    static CACHE: [OnceLock<Arc<Image>>; 6 * BAND_STEPS] =
        [const { OnceLock::new() }; 6 * BAND_STEPS];
    let st = step % BAND_STEPS;
    let idx = continent.index() * BAND_STEPS + st;
    CACHE[idx]
        .get_or_init(|| {
            let geo = coastline_cache(continent);
            let head = (st as f32 / BAND_STEPS as f32) * 1000.0;
            let d_wide = build_coastline_svg_d(geo, head, 210.0);
            let d_mid = build_coastline_svg_d(geo, head + 26.0, 162.0);
            let d_warm = build_coastline_svg_d(geo, head + 56.0, 118.0);
            let d_core = build_coastline_svg_d(geo, head + 86.0, 74.0);
            let doc = format!(
                r##"<svg xmlns="http://www.w3.org/2000/svg" width="596" height="298" viewBox="-28 -28 596 298" fill="none"><path d="{d_wide}" fill="none" stroke="#ff7fa6" stroke-width="15" stroke-opacity="0.11" stroke-linecap="round" stroke-linejoin="round"/><path d="{d_wide}" fill="none" stroke="#ff98b6" stroke-width="9.5" stroke-opacity="0.19" stroke-linecap="round" stroke-linejoin="round"/><path d="{d_mid}" fill="none" stroke="#ffb3c6" stroke-width="5.5" stroke-opacity="0.34" stroke-linecap="round" stroke-linejoin="round"/><path d="{d_warm}" fill="none" stroke="#ffd6e2" stroke-width="3.0" stroke-opacity="0.54" stroke-linecap="round" stroke-linejoin="round"/><path d="{d_core}" fill="none" stroke="#ffffff" stroke-width="1.8" stroke-opacity="0.72" stroke-linecap="round" stroke-linejoin="round"/></svg>"##
            );
            Arc::new(Image::from_bytes(ImageFormat::Svg, doc.into_bytes()))
        })
        .clone()
}

/// Unclipped crisp stepped SVG `<path>` coastline shine rendered above the highlighted continent.
fn continent_top_band_svg(continent: Continent, step: usize) -> Arc<Image> {
    static CACHE: [OnceLock<Arc<Image>>; 6 * BAND_STEPS] =
        [const { OnceLock::new() }; 6 * BAND_STEPS];
    let st = step % BAND_STEPS;
    let idx = continent.index() * BAND_STEPS + st;
    CACHE[idx]
        .get_or_init(|| {
            let geo = coastline_cache(continent);
            let head = (st as f32 / BAND_STEPS as f32) * 1000.0;
            let d_tail = build_coastline_svg_d(geo, head, 210.0);
            let d_body = build_coastline_svg_d(geo, head + 52.0, 148.0);
            let d_head = build_coastline_svg_d(geo, head + 104.0, 88.0);
            let doc = format!(
                r##"<svg xmlns="http://www.w3.org/2000/svg" width="596" height="298" viewBox="-28 -28 596 298" fill="none"><path d="{d_tail}" fill="none" stroke="#ff94b2" stroke-width="1.5" stroke-opacity="0.42" stroke-linecap="round" stroke-linejoin="round"/><path d="{d_body}" fill="none" stroke="#ffc2d4" stroke-width="1.65" stroke-opacity="0.76" stroke-linecap="round" stroke-linejoin="round"/><path d="{d_head}" fill="none" stroke="#fff7fa" stroke-width="1.8" stroke-opacity="0.96" stroke-linecap="round" stroke-linejoin="round"/></svg>"##
            );
            Arc::new(Image::from_bytes(ImageFormat::Svg, doc.into_bytes()))
        })
        .clone()
}

/// Cached crisp SVG of the gray world base inside the generous padded viewBox (`2` static entries: light & dark).
fn world_base_svg(dark: bool) -> Arc<Image> {
    static LIGHT_BASE: OnceLock<Arc<Image>> = OnceLock::new();
    static DARK_BASE: OnceLock<Arc<Image>> = OnceLock::new();
    let slot = if dark { &DARK_BASE } else { &LIGHT_BASE };
    slot.get_or_init(|| {
        let fill_hex = if dark { "#2a2a2d" } else { "#E8E8E8" };
        let mut paths = String::with_capacity(30_000);
        for c in Continent::ALL {
            paths.push_str(r#"<path d=""#);
            paths.push_str(c.svg_path());
            paths.push_str(r#""/>"#);
        }
        let doc = format!(
            r#"<svg xmlns="http://www.w3.org/2000/svg" width="596" height="298" viewBox="-28 -28 596 298" fill="none"><g fill="{fill_hex}" stroke="{fill_hex}" stroke-width="0.5" stroke-linejoin="round">{paths}</g></svg>"#
        );
        Arc::new(Image::from_bytes(ImageFormat::Svg, doc.into_bytes()))
    })
    .clone()
}

/// Cached crisp SVG of a single highlighted continent with unclipped multi-pass `<path>` elevation shadow (zero `<filter>`).
fn continent_focus_svg(dark: bool, continent: Continent) -> Arc<Image> {
    static CACHE: [OnceLock<Arc<Image>>; 12] = [const { OnceLock::new() }; 12];
    let idx = usize::from(dark) * 6 + continent.index();
    CACHE[idx]
        .get_or_init(|| {
            let (fill_hex, stroke_hex, stroke_op, drop_hex, sh_a1, sh_a2, sh_a3) = if dark {
                ("#46464c", "#ffffff", "0.14", "#000000", "0.10", "0.16", "0.24")
            } else {
                ("#FFFFFF", "#E2E2E2", "1.0", "#1F2128", "0.025", "0.04", "0.06")
            };
            let d = continent.svg_path();
            let doc = format!(
                r#"<svg xmlns="http://www.w3.org/2000/svg" width="596" height="298" viewBox="-28 -28 596 298" fill="none"><path d="{d}" transform="translate(0 2.4)" fill="{drop_hex}" fill-opacity="{sh_a1}" stroke="{drop_hex}" stroke-width="5.6" stroke-opacity="{sh_a1}" stroke-linecap="round" stroke-linejoin="round"/><path d="{d}" transform="translate(0 1.6)" fill="{drop_hex}" fill-opacity="{sh_a2}" stroke="{drop_hex}" stroke-width="3.0" stroke-opacity="{sh_a2}" stroke-linecap="round" stroke-linejoin="round"/><path d="{d}" transform="translate(0 0.8)" fill="{drop_hex}" fill-opacity="{sh_a3}" stroke="{drop_hex}" stroke-width="1.2" stroke-opacity="{sh_a3}" stroke-linecap="round" stroke-linejoin="round"/><path d="{d}" fill="{fill_hex}" stroke="{stroke_hex}" stroke-opacity="{stroke_op}" stroke-width="0.55" stroke-linejoin="round"/></svg>"#
            );
            Arc::new(Image::from_bytes(ImageFormat::Svg, doc.into_bytes()))
        })
        .clone()
}

/// Continental world map illustration with one highlighted continent, pastel coastline band, and pill switcher.
///
/// # Examples
///
/// ```no_run
/// use gpui::prelude::*;
/// use kui::components::world_map::{Continent, WorldMap};
///
/// # fn example(cx: &mut gpui::App) {
/// let _map = cx.new(|cx| WorldMap::new("market-map", cx).with_continent(Continent::Europe));
/// # }
/// ```
pub struct WorldMap {
    id: ElementId,
    focus: FocusHandle,
    active_continent: Continent,
    prev_continent: Option<(Continent, Instant)>,
    entered_at: Instant,
    band_started_at: Instant,
    initial_mount: bool,
    show_switcher: bool,
    menu_open: bool,
    highlighted_idx: usize,
    hovered_map_continent: Option<Continent>,
    preview_slides: [Slide; 6],
    map_press: Slide,
    label: Option<SharedString>,
    playing: bool,
    height: Option<Pixels>,
    loading: bool,
    empty: bool,
    measured_size: Rc<Cell<(f32, f32)>>,
    map_bounds: Rc<Cell<Bounds<Pixels>>>,
}

impl WorldMap {
    /// Create a [`WorldMap`] highlighting [`Continent::Europe`] with the top-left switcher pill enabled.
    pub fn new(id: impl Into<ElementId>, cx: &mut Context<Self>) -> Self {
        cx.observe_global::<Theme>(|_, cx| cx.notify()).detach();
        cx.observe_global::<UiLanguage>(|_, cx| cx.notify())
            .detach();
        let now = cx.background_executor().now();
        Self {
            id: id.into(),
            focus: cx.focus_handle().tab_stop(true),
            active_continent: Continent::Europe,
            prev_continent: None,
            entered_at: now,
            band_started_at: now,
            initial_mount: true,
            show_switcher: true,
            menu_open: false,
            highlighted_idx: Continent::Europe.index(),
            hovered_map_continent: None,
            preview_slides: [
                Slide::snappy(0.),
                Slide::snappy(0.),
                Slide::snappy(0.),
                Slide::snappy(0.),
                Slide::snappy(0.),
                Slide::snappy(0.),
            ],
            map_press: Slide::snappy(0.),
            label: None,
            playing: true,
            height: None,
            loading: false,
            empty: false,
            measured_size: Rc::new(Cell::new((560.0, 251.0))),
            map_bounds: Rc::new(Cell::new(Bounds::default())),
        }
    }

    /// Set the highlighted continent (`Continent::Europe` by default).
    pub fn with_continent(mut self, continent: Continent) -> Self {
        self.active_continent = continent;
        self.highlighted_idx = continent.index();
        self
    }

    /// Alias for [`Self::with_continent`] matching `defaultContinent`.
    pub fn with_default_continent(self, continent: Continent) -> Self {
        self.with_continent(continent)
    }

    /// Show or hide the interactive continent pill switcher in the top-left corner (`true` default).
    pub fn with_show_switcher(mut self, show: bool) -> Self {
        self.show_switcher = show;
        self
    }

    /// Override the accessible map description (`"World map with <Continent> highlighted"` by default).
    pub fn with_label(mut self, label: impl Into<SharedString>) -> Self {
        self.label = Some(label.into());
        self
    }

    /// Control whether the pastel coastline band travels continuously (`true` default).
    pub fn with_playing(mut self, playing: bool) -> Self {
        self.playing = playing;
        self
    }

    /// Override the explicit container height (otherwise scales `540 : 242` from width).
    pub fn with_height(mut self, height: Pixels) -> Self {
        self.height = Some(height);
        self
    }

    /// Configure the skeleton loading state.
    pub fn with_loading(mut self, loading: bool) -> Self {
        self.loading = loading;
        self
    }

    /// Configure the empty state.
    pub fn with_empty(mut self, empty: bool) -> Self {
        self.empty = empty;
        self
    }

    /// Return the currently highlighted [`Continent`].
    pub fn continent(&self) -> Continent {
        self.active_continent
    }

    /// Switch to `continent` with smooth crossfade and coastline reset.
    pub fn set_continent(&mut self, continent: Continent, cx: &mut Context<Self>) {
        if self.active_continent == continent {
            if self.menu_open {
                self.set_menu_open(false, cx);
            }
            return;
        }
        let now = cx.background_executor().now();
        self.prev_continent = Some((self.active_continent, now));
        self.active_continent = continent;
        self.highlighted_idx = continent.index();
        self.entered_at = now;
        self.band_started_at = now;
        self.initial_mount = false;
        if self.menu_open {
            self.menu_open = false;
            cx.emit(WorldMapEvent::MenuOpenChanged(false));
        }
        cx.emit(WorldMapEvent::ContinentChanged(continent));
        cx.notify();
    }

    fn hit_map_pos(&self, pos: Point<Pixels>) -> Option<Continent> {
        let b = self.map_bounds.get();
        let bw = f32::from(b.size.width);
        let bh = f32::from(b.size.height);
        if bw <= 4.0 || bh <= 4.0 {
            return None;
        }
        let vx = (f32::from(pos.x - b.left()) / bw) * MAP_VB_W;
        let vy = (f32::from(pos.y - b.top()) / bh) * MAP_VB_H;
        hit_continent_vb(vx, vy)
    }

    /// Return whether the continent switcher menu is open.
    pub fn is_menu_open(&self) -> bool {
        self.menu_open
    }

    /// Open or close the continent switcher menu.
    pub fn set_menu_open(&mut self, open: bool, cx: &mut Context<Self>) {
        if self.menu_open != open {
            self.menu_open = open;
            if open {
                self.highlighted_idx = self.active_continent.index();
            }
            cx.emit(WorldMapEvent::MenuOpenChanged(open));
            cx.notify();
        }
    }

    /// Toggle skeleton loading mode at runtime.
    pub fn set_loading(&mut self, loading: bool, cx: &mut Context<Self>) {
        if self.loading != loading {
            self.loading = loading;
            cx.notify();
        }
    }

    /// Return whether skeleton loading mode is active.
    pub fn is_loading(&self) -> bool {
        self.loading
    }

    /// Toggle the empty state at runtime.
    pub fn set_empty(&mut self, empty: bool, cx: &mut Context<Self>) {
        if self.empty != empty {
            self.empty = empty;
            cx.notify();
        }
    }

    /// Return whether the empty state is active.
    pub fn is_empty(&self) -> bool {
        self.empty
    }
}

impl Render for WorldMap {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let p = ProPalette::get(cx);
        let reduced = disabled_motion(cx);
        let now = cx.background_executor().now();
        let band_elapsed = now
            .saturating_duration_since(self.band_started_at)
            .as_secs_f32();

        if self.loading {
            let phase = (band_elapsed / 1.4).fract();
            if !reduced {
                w.request_animation_frame();
            }
            return div()
                .id(self.id.clone())
                .w_full()
                .h(self.height.unwrap_or(px(260.0)))
                .flex()
                .items_center()
                .justify_center()
                .child(pro_skeleton_bar(480.0, 215.0, 16.0, phase, cx))
                .into_any_element();
        }

        if self.empty {
            return div()
                .id(self.id.clone())
                .w_full()
                .child(pro_empty_state(
                    ProIcon::Globe,
                    tr(cx, "No region selected", "未选择覆盖大洲"),
                    tr(
                        cx,
                        "Select a continent to highlight regional market coverage.",
                        "选择一个大洲以高亮展示区域覆盖范围。",
                    ),
                    None,
                    cx,
                ))
                .into_any_element();
        }

        let animate_band = self.playing && !reduced;
        let mut exit_state: Option<(Continent, f32)> = None;
        if let Some((prev_c, t0)) = self.prev_continent {
            let age = now.saturating_duration_since(t0).as_secs_f32();
            if !reduced && age < 0.32 {
                let u = (age / 0.32).clamp(0.0, 1.0);
                exit_state = Some((prev_c, 1.0 - u * u));
            } else {
                self.prev_continent = None;
            }
        }

        let enter_age = now.saturating_duration_since(self.entered_at).as_secs_f32();
        let enter_t = if self.initial_mount || reduced || enter_age >= 0.52 {
            1.0
        } else {
            pro_ease((enter_age / 0.52).clamp(0.0, 1.0))
        };

        if animate_band || exit_state.is_some() || enter_t < 0.999 {
            w.request_animation_frame();
        }

        let head_norm = if animate_band {
            (INITIAL_BAND_PHASE + band_elapsed / BAND_LOOP_SECS).fract() * 1000.0
        } else {
            INITIAL_BAND_PHASE * 1000.0
        };

        let size_cell = self.measured_size.clone();
        let (raw_w, _) = size_cell.get();
        let stage_pad_x = if raw_w > 520.0 { 28.0 } else { 14.0 };
        let stage_pad_y = if self.height.is_some() { 0.0 } else { 20.0 };
        let meas_w = (raw_w - stage_pad_x * 2.0).max(220.0);
        let auto_h = (meas_w * (MAP_VB_H / MAP_VB_W)).clamp(190.0, 400.0);
        // Reserve vertical room when the switcher menu is open on compact containers
        let min_open_h = if self.menu_open { 256.0 } else { 190.0 };
        let resolved_h = self
            .height
            .unwrap_or_else(|| px(auto_h.max(min_open_h) + stage_pad_y * 2.0));
        let eff_h = (f32::from(resolved_h) - stage_pad_y * 2.0).max(160.0);
        let scale = (meas_w / MAP_VB_W).min(eff_h / MAP_VB_H).max(0.45);
        let map_w = MAP_VB_W * scale;
        let map_h = MAP_VB_H * scale;

        let dark = p.dark;
        let active = self.active_continent;
        let hi_idx = self.highlighted_idx.min(Continent::ALL.len() - 1);
        let preview_target = if self.menu_open && Continent::ALL[hi_idx] != active {
            Some(Continent::ALL[hi_idx])
        } else {
            self.hovered_map_continent.filter(|&c| c != active)
        };
        let mut preview_vals = [0.0f32; 6];
        for c in Continent::ALL {
            let ci = c.index();
            let tgt = if preview_target == Some(c) { 1.0 } else { 0.0 };
            self.preview_slides[ci].duration(tgt, 0.18, cx);
            preview_vals[ci] = self.preview_slides[ci].get(w, cx).clamp(0., 1.);
        }
        let map_down = self.map_press.get(w, cx).clamp(0., 1.);
        let active_name = active.label(cx);
        let aria_label: SharedString = self.label.clone().unwrap_or_else(|| {
            if UiLanguage::current(cx) == UiLanguage::Chinese {
                format!("世界地图（当前高亮：{active_name}）").into()
            } else {
                format!("World map with {active_name} highlighted").into()
            }
        });

        let base_img = world_base_svg(dark);
        let focus_img = continent_focus_svg(dark, active);
        let band_step = (((head_norm / 1000.0).rem_euclid(1.0) * BAND_STEPS as f32).round()
            as usize)
            % BAND_STEPS;
        let under_glow_img = continent_under_glow_svg(active, band_step);
        let top_band_img = continent_top_band_svg(active, band_step);

        let pad_px = VB_PAD * scale;
        let full_w_px = VB_FULL_W * scale;
        let full_h_px = VB_FULL_H * scale;

        // Subtle `0.94 -> 1.0` scale settle around the active continent's focal origin (+ tactile press)
        let enter_scale = (0.94 + 0.06 * enter_t) * (1.0 - 0.012 * map_down);
        let (orig_x, orig_y) = active.origin();
        let focus_scale = scale * enter_scale;
        let focus_pad_px = VB_PAD * focus_scale;
        let focus_full_w = VB_FULL_W * focus_scale;
        let focus_full_h = VB_FULL_H * focus_scale;
        let focus_w = map_w * enter_scale;
        let focus_h = map_h * enter_scale;
        let focus_dx = (orig_x * scale) * (1.0 - enter_scale);
        let focus_dy = (orig_y * scale) * (1.0 - enter_scale);
        let glow_alpha = if dark { 0.94 } else { 0.88 };

        let map_bounds_cell = self.map_bounds.clone();
        let hovering_land = self.hovered_map_continent.is_some();
        let mut map_stage = div()
            .id(pro_eid(&self.id, "map-backdrop"))
            .relative()
            .w(px(map_w))
            .h(px(map_h))
            .flex_none()
            .when(hovering_land, |d| d.cursor_pointer())
            .on_mouse_move(cx.listener(|this, ev: &MouseMoveEvent, _, cx| {
                let hit = this.hit_map_pos(ev.position);
                if this.hovered_map_continent != hit {
                    this.hovered_map_continent = hit;
                    for c in Continent::ALL {
                        let tgt = if hit == Some(c) && c != this.active_continent {
                            1.0
                        } else {
                            0.0
                        };
                        this.preview_slides[c.index()].duration(tgt, 0.18, cx);
                    }
                    cx.notify();
                }
            }))
            .on_hover(cx.listener(|this, inside: &bool, _, cx| {
                if !*inside && this.hovered_map_continent.take().is_some() {
                    this.map_press.duration(0., 0.14, cx);
                    cx.notify();
                }
            }))
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|this, ev: &MouseDownEvent, _, cx| {
                    this.map_press.duration(1., 0.08, cx);
                    if let Some(hit) = this.hit_map_pos(ev.position) {
                        this.set_continent(hit, cx);
                    } else if this.menu_open {
                        this.set_menu_open(false, cx);
                    }
                    cx.notify();
                }),
            )
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(|this, _: &MouseUpEvent, _, cx| {
                    this.map_press.duration(0., 0.14, cx);
                    cx.notify();
                }),
            )
            .on_mouse_up_out(
                MouseButton::Left,
                cx.listener(|this, _: &MouseUpEvent, _, cx| {
                    this.map_press.duration(0., 0.14, cx);
                    cx.notify();
                }),
            )
            .child(
                canvas(move |b, _, _| map_bounds_cell.set(b), |_, _, _, _| ())
                    .absolute()
                    .inset_0(),
            )
            .child(
                img(base_img)
                    .w(px(full_w_px))
                    .h(px(full_h_px))
                    .absolute()
                    .left(px(-pad_px))
                    .top(px(-pad_px)),
            );

        // Smooth `Slide::snappy` hover preview silhouettes + subtle coastline shimmer for non-active continents
        for c in Continent::ALL {
            if c == active {
                continue;
            }
            let pv = preview_vals[c.index()];
            if pv > 0.01 {
                let prev_svg = continent_focus_svg(dark, c);
                let prev_band_svg = continent_top_band_svg(c, band_step);
                map_stage = map_stage.child(
                    div()
                        .absolute()
                        .inset_0()
                        .opacity(pv * 0.68)
                        .child(
                            img(prev_svg)
                                .w(px(full_w_px))
                                .h(px(full_h_px))
                                .absolute()
                                .left(px(-pad_px))
                                .top(px(-pad_px)),
                        )
                        .child(
                            img(prev_band_svg)
                                .w(px(full_w_px))
                                .h(px(full_h_px))
                                .absolute()
                                .left(px(-pad_px))
                                .top(px(-pad_px))
                                .opacity(0.55),
                        ),
                );
            }
        }

        if let Some((prev_c, exit_a)) = exit_state {
            let prev_img = continent_focus_svg(dark, prev_c);
            map_stage = map_stage.child(
                img(prev_img)
                    .w(px(full_w_px))
                    .h(px(full_h_px))
                    .absolute()
                    .left(px(-pad_px))
                    .top(px(-pad_px))
                    .opacity(exit_a),
            );
        }

        // Active continent composite group (`under_glow -> opaque continent SVG -> sharp 3-layer band`)
        map_stage = map_stage.child(
            div()
                .absolute()
                .left(px(focus_dx))
                .top(px(focus_dy))
                .w(px(focus_w))
                .h(px(focus_h))
                .opacity(enter_t)
                .child(
                    img(under_glow_img)
                        .w(px(focus_full_w))
                        .h(px(focus_full_h))
                        .absolute()
                        .left(px(-focus_pad_px))
                        .top(px(-focus_pad_px))
                        .opacity(glow_alpha),
                )
                .child(
                    img(focus_img)
                        .w(px(focus_full_w))
                        .h(px(focus_full_h))
                        .absolute()
                        .left(px(-focus_pad_px))
                        .top(px(-focus_pad_px)),
                )
                .child(
                    img(top_band_img)
                        .w(px(focus_full_w))
                        .h(px(focus_full_h))
                        .absolute()
                        .left(px(-focus_pad_px))
                        .top(px(-focus_pad_px)),
                ),
        );

        // Top-left interactive continent capsule switcher + morphing listbox
        if self.show_switcher {
            let trig_bg: Hsla = if dark {
                rgb(0x232326).into()
            } else {
                rgb(0xffffff).into()
            };
            let trig_border: Hsla = if dark {
                hsla(0.0, 0.0, 1.0, 0.08)
            } else {
                rgb(0xe5e5e5).into()
            };
            let trig_fg: Hsla = if dark {
                rgb(0xededed).into()
            } else {
                rgb(0x171717).into()
            };
            let chev_col: Hsla = if dark {
                rgb(0x8f8f8f).into()
            } else {
                rgb(0x737373).into()
            };
            let row_fill: Hsla = if dark {
                rgb(0x2a2a2d).into()
            } else {
                rgb(0xf5f5f5).into()
            };

            let chev_icon = if self.menu_open {
                ProIcon::ChevronUp
            } else {
                ProIcon::ChevronDown
            };

            let trigger_pill = div()
                .flex_none()
                .on_mouse_down(MouseButton::Left, |_, _, cx| {
                    cx.stop_propagation();
                })
                .child(pro_tactile(
                    pro_eid(&self.id, "switcher-trigger"),
                    format!("{}: {active_name}", tr(cx, "Continent", "大洲")),
                    9999.,
                    trig_bg,
                    pro_mix_color(trig_bg, row_fill, 0.58),
                    trig_border,
                    p.line_strong,
                    self.menu_open,
                    div()
                        .h(px(28.0))
                        .pl(px(12.0))
                        .pr(px(8.0))
                        .flex()
                        .items_center()
                        .gap(px(4.0))
                        .child(pro_swap_label(
                            pro_eid(&self.id, "trig-lbl"),
                            active_name,
                            13.0,
                            FontWeight::MEDIUM,
                            trig_fg,
                        ))
                        .child(pro_icon(chev_icon, 14.0, chev_col)),
                    cx,
                    |this, w, cx| {
                        let next = !this.menu_open;
                        this.set_menu_open(next, cx);
                        this.focus.focus(w, cx);
                    },
                ));

            let sensor = pro_selection_sensor();
            let hi_key: SharedString = Continent::ALL[hi_idx].as_slug().into();
            let entity = cx.entity();

            let mut rows_col =
                div()
                    .relative()
                    .w_full()
                    .flex()
                    .flex_col()
                    .child(pro_pill_indicator(
                        pro_eid(&self.id, "menu-row-ind"),
                        hi_key,
                        sensor.clone(),
                        10.0,
                        row_fill,
                        None,
                        false,
                    ));

            for (idx, c) in Continent::ALL.into_iter().enumerate() {
                let is_selected = c == active;
                let is_hi = idx == hi_idx;
                let c_label = c.label(cx);
                let ent_hover = entity.clone();
                let ent_click = entity.clone();
                rows_col = rows_col.child(
                    div()
                        .id(pro_eid(&self.id, format!("opt-{}", c.as_slug())))
                        .role(Role::ListItem)
                        .aria_label(c_label)
                        .relative()
                        .w_full()
                        .h(px(31.0))
                        .pl(px(10.0))
                        .pr(px(8.0))
                        .rounded(px(10.0))
                        .flex()
                        .items_center()
                        .justify_between()
                        .gap(px(8.0))
                        .cursor_pointer()
                        .when(is_hi, |d| d.child(pro_mark_selected(&sensor)))
                        .on_hover(move |inside, _, cx| {
                            if *inside {
                                ent_hover.update(cx, |this, cx| {
                                    if this.highlighted_idx != idx {
                                        this.highlighted_idx = idx;
                                        cx.notify();
                                    }
                                });
                            }
                        })
                        .on_mouse_down(MouseButton::Left, |_, _, cx| {
                            cx.stop_propagation();
                        })
                        .on_click(move |_, _, cx| {
                            ent_click.update(cx, |this, cx| {
                                this.set_continent(c, cx);
                            });
                        })
                        .child(
                            div()
                                .flex_1()
                                .min_w_0()
                                .whitespace_nowrap()
                                .text_size(px(13.0))
                                .line_height(px(18.0))
                                .font_weight(FontWeight::MEDIUM)
                                .text_color(trig_fg)
                                .child(c_label),
                        )
                        .child(div().size(px(15.0)).flex_none().child(pro_check_draw(
                            pro_eid(&self.id, format!("chk-{}", c.as_slug())),
                            is_selected,
                            15.0,
                            false,
                            trig_fg,
                        ))),
                );
            }

            let menu_layer = pro_presence(
                pro_eid(&self.id, "switcher-menu"),
                self.menu_open,
                0.24,
                0.18,
                move |amt| {
                    let dy = -4.0 * (1.0 - amt);
                    div()
                        .absolute()
                        .top(px(34.0 + dy))
                        .left_0()
                        .w(px(172.0))
                        .p(px(5.0))
                        .rounded(px(16.0))
                        .bg(trig_bg)
                        .border_1()
                        .border_color(trig_border)
                        .shadow_md()
                        .opacity(amt)
                        .on_mouse_down(MouseButton::Left, |_, _, cx| {
                            cx.stop_propagation();
                        })
                        .child(rows_col)
                        .into_any_element()
                },
            );

            map_stage = map_stage.child(
                div()
                    .absolute()
                    .left(px(12.0))
                    .top(px(12.0))
                    .flex()
                    .flex_col()
                    .items_start()
                    .child(trigger_pill)
                    .child(menu_layer),
            );
        }

        let measure_sensor = canvas(
            move |bounds, window, _| {
                let bw = f32::from(bounds.size.width);
                let bh = f32::from(bounds.size.height);
                if bw > 16.0 && bh > 16.0 {
                    let prev = size_cell.get();
                    if (bw - prev.0).abs() > 1.0 || (bh - prev.1).abs() > 1.0 {
                        size_cell.set((bw, bh));
                        window.request_animation_frame();
                    }
                }
            },
            |_, _, _, _| (),
        )
        .absolute()
        .inset_0();

        div()
            .id(self.id.clone())
            .track_focus(&self.focus)
            .role(Role::Image)
            .aria_label(aria_label)
            .on_key_down(cx.listener(|this, ev: &KeyDownEvent, _, cx| {
                if !this.show_switcher {
                    return;
                }
                let key = ev.keystroke.key.as_str();
                if !this.menu_open {
                    match key {
                        "down" | "up" | "enter" | "space" => {
                            this.set_menu_open(true, cx);
                        }
                        _ => {}
                    }
                    return;
                }
                let last = Continent::ALL.len() - 1;
                match key {
                    "down" => {
                        this.highlighted_idx = (this.highlighted_idx + 1).min(last);
                        cx.notify();
                    }
                    "up" => {
                        this.highlighted_idx = this.highlighted_idx.saturating_sub(1);
                        cx.notify();
                    }
                    "home" => {
                        this.highlighted_idx = 0;
                        cx.notify();
                    }
                    "end" => {
                        this.highlighted_idx = last;
                        cx.notify();
                    }
                    "enter" | "space" => {
                        let chosen = Continent::ALL[this.highlighted_idx.min(last)];
                        this.set_continent(chosen, cx);
                    }
                    "escape" | "tab" => {
                        this.set_menu_open(false, cx);
                    }
                    _ => {}
                }
            }))
            .relative()
            .w_full()
            .h(resolved_h)
            .flex()
            .items_center()
            .justify_center()
            .child(measure_sensor)
            .child(map_stage)
            .into_any_element()
    }
}

#[cfg(test)]
mod tests {
    use super::{
        Continent, MAP_VB_H, MAP_VB_W, WorldMap, WorldMapEvent, coastline_cache,
        coastline_pastel_color, hit_continent_vb, scan_svg_numbers,
    };
    use gpui::{
        MouseButton, MouseDownEvent, MouseMoveEvent, MouseUpEvent, TestAppContext, point, px, size,
    };
    use std::{cell::RefCell, rc::Rc, time::Duration};

    #[test]
    fn compact_svg_number_scanner_and_all_six_coastlines_parse_cleanly() {
        let parsed = scan_svg_numbers("M90.1 18.6l 2.3-.5 3.3-.6 .9 0-1.1 .6z");
        assert_eq!(parsed.len(), 10);
        assert!((parsed[0] - 90.1).abs() < 1e-4);
        assert!((parsed[3] - (-0.5)).abs() < 1e-4);
        assert!((parsed[8] - (-1.1)).abs() < 1e-4);

        let expected_pts = [692usize, 250, 384, 352, 679, 224];
        for (c, exp_n) in Continent::ALL.into_iter().zip(expected_pts) {
            assert_eq!(Continent::from_slug(c.as_slug()), Some(c));
            let geo = coastline_cache(c);
            assert_eq!(geo.pts.len(), exp_n);
            assert!(geo.arc_length > 200.0);
            let last_s = *geo.norm_s.last().expect("closed coastline s");
            assert!((last_s - 1000.0).abs() < 1e-2);
            assert_eq!(geo.pts.first(), geo.pts.last());
        }
    }

    #[test]
    fn diagonal_coastline_gradient_transitions_from_coral_to_periwinkle() {
        let nw = coastline_pastel_color(40.0, 20.0);
        let se = coastline_pastel_color(500.0, 220.0);
        assert_ne!(nw, se);
        assert_eq!(Continent::default(), Continent::Europe);
        assert_eq!(hit_continent_vb(100.0, 60.0), Some(Continent::NorthAmerica));
        assert_eq!(hit_continent_vb(300.0, 125.0), Some(Continent::Africa));
    }

    #[gpui::test]
    fn hovering_map_region_previews_continent_highlight_and_click_selects(cx: &mut TestAppContext) {
        cx.update(crate::init);
        let exec = cx.executor();
        let events: Rc<RefCell<Vec<WorldMapEvent>>> = Rc::new(RefCell::new(Vec::new()));
        let ev_sink = events.clone();

        let (view, vcx) = cx.add_window_view(|_, cx| {
            let wm = WorldMap::new("wm-test", cx);
            cx.subscribe_self(move |_, ev: &WorldMapEvent, _| {
                ev_sink.borrow_mut().push(ev.clone());
            })
            .detach();
            wm
        });
        vcx.simulate_resize(size(px(620.), px(320.)));
        vcx.update(|w, app| w.simulate_next_frame(app));
        vcx.run_until_parked();

        // Map `(100, 60)` in `540 × 242` viewBox (heart of North America) into window coordinates
        let na_pt = vcx.update(|_, app| {
            let b = view.read(app).map_bounds.get();
            point(
                b.left() + b.size.width * (100.0 / MAP_VB_W),
                b.top() + b.size.height * (60.0 / MAP_VB_H),
            )
        });

        vcx.simulate_event(MouseMoveEvent {
            position: na_pt,
            pressed_button: None,
            modifiers: Default::default(),
        });
        exec.advance_clock(Duration::from_millis(160));
        vcx.update(|w, app| w.simulate_next_frame(app));
        vcx.run_until_parked();

        vcx.update(|_, app| {
            let wm = view.read(app);
            assert_eq!(wm.hovered_map_continent, Some(Continent::NorthAmerica));
            assert!(
                wm.preview_slides[Continent::NorthAmerica.index()].value(app) > 0.65,
                "expected smooth Slide::snappy preview highlight on North America"
            );
        });

        vcx.simulate_event(MouseDownEvent {
            position: na_pt,
            button: MouseButton::Left,
            modifiers: Default::default(),
            click_count: 1,
            first_mouse: false,
        });
        vcx.simulate_event(MouseUpEvent {
            position: na_pt,
            button: MouseButton::Left,
            modifiers: Default::default(),
            click_count: 1,
        });
        vcx.run_until_parked();

        assert_eq!(
            vcx.update(|_, app| view.read(app).continent()),
            Continent::NorthAmerica
        );
        assert!(
            events
                .borrow()
                .contains(&WorldMapEvent::ContinentChanged(Continent::NorthAmerica))
        );
    }
}
